ETR_ENTRUST_ADD.TERM_TYPE termType,
ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1, if( ETR_ENTRUST_ADD.ASSET_TYPE='F01', IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0), if( ETR_ENTRUST_ADD.ASSET_TYPE='F10', IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0), IFNULL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM) ) ) entrustAmt, if( ETR_ENTRUST_ADD.ASSET_TYPE='F01', IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0), if ( ETR_ENTRUST_ADD.ASSET_TYPE='F10', IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0), IFNULL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM) ) ) - if( ETR_ENTRUST_ADD.ASSET_TYPE='F01', IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0), if( ETR_ENTRUST_ADD.ASSET_TYPE='F10', IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0), IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT,0) ) ) proAvailableCash, if(ETR_ENTRUST_ADD.CONTRACT_RESULT='已签署完毕',ETR_ENTRUST.ENTRUST_AMT,0) finishAmt, if(ETR_ENTRUST_ADD.CONTRACT_RESULT='已签署完毕',1,0) percent, ETR_ENTRUST.CCY ccy, ETR_DISTRIBUTE.TRADER trader, ETR_ENTRUST.REMARK remark, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, (STR_TO_DATE(trunc(ETR_ENTRUST.MDATE)) - STR_TO_DATE(trunc(NOW()))) days, ETR_ENTRUST_ADD.TERM_DAYS repoTerm, ETR_ENTRUST.price price, ETR_ENTRUST_ADD.MATURE_YIELD matureYield, ETR_ENTRUST_ADD.EXER_YIELD exerYield, ETR_ENTRUST.PRICE_MODEL priceMode FROM ETR_DISTRIBUTE INNER JOIN ETR_ENTRUST ON ETR_DISTRIBUTE.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT ETR_FINISH_STATUS.ENTRUST_ID,sum(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) ETR_FINISH_STATUS_A ON ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
