and wtpdp.IS_CANCEL='N' and wtpdp.TRADE_STATUS = '01' and not exists (select 1 from trd_match_info where PRE_TRADE_ID = wtpdp.trade_id)
order by wtpdp.trade_date desc ) union all select * from ( SELECT ETR_ENTRUST.ENTRUST_ID entrustId, '02' tradeType, '投资指令' tradeTypeName, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.ENTRUST_DATE createTimeVal, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE finprodType2, ETR_ENTRUST.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, ETR_ENTRUST.PS ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, case when ETR_ENTRUST_ADD.SETTLE_SPREED=0 then '01' when ETR_ENTRUST_ADD.SETTLE_SPREED=1 then '02' when ETR_ENTRUST_ADD.SETTLE_SPREED=2 then '03' end settleSpeed,
case when ETR_ENTRUST_ADD.ASSET_TYPE='F01' then IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0) when ETR_ENTRUST_ADD.ASSET_TYPE='F10' then IFNULL(ETR_ENTRUST.ENTRUST_NUM *100,0) else IFNULL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM) end entrustAmt, null prinAmt, null tradeAmt, if ( ETR_ENTRUST_ADD.ASSET_TYPE='F01', IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0), if ( ETR_ENTRUST_ADD.ASSET_TYPE='F10', IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0), IFNULL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM) ) )- if( ETR_ENTRUST_ADD.ASSET_TYPE='F01', IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0), if( ETR_ENTRUST_ADD.ASSET_TYPE='F10', IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0), IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT,0) ) ) proAvailableCash, case when ETR_ENTRUST_ADD.ASSET_TYPE= 'F01' then IFNULL(ETR_FINISH_STATUS_B.FINISH_AMT * 100, 0) when ETR_ENTRUST_ADD.ASSET_TYPE= 'F10' then IFNULL(ETR_FINISH_STATUS_B.FINISH_AMT * 100, 0) else IFNULL(ETR_FINISH_STATUS_B.FINISH_AMT, 0) end finshAmt, round(ETR_FINISH_STATUS_B.FINISH_AMT/IFNULL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM),4) percent, ETR_ENTRUST.CHL_ID chlId, ETR_ENTRUST_ADD.SEC_ACCT_ID secAcctId, ETR_ENTRUST.CCY ccy, ETR_DISTRIBUTE.TRADER trader, ETR_ENTRUST.REMARK remark, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST.price price, ETR_ENTRUST_ADD.MATURE_YIELD matureYield, ETR_ENTRUST_ADD.EXER_YIELD exerYield, ETR_ENTRUST.PRICE_MODEL priceMode, ETR_ENTRUST_ADD.TERM_DAYS repoTerm FROM ETR_DISTRIBUTE INNER JOIN ETR_ENTRUST ON ETR_DISTRIBUTE.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT ETR_FINISH_STATUS.ENTRUST_ID,sum(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) ETR_FINISH_STATUS_A ON ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ENTRUST_ID,TRADE_ID, sum(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID,TRADE_ID) ETR_FINISH_STATUS_B ON ETR_FINISH_STATUS_B.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID AND ETR_FINISH_STATUS_B.TRADE_ID NOT IN (SELECT CSTP_TRADE_ID FROM TRD_MATCH_INFO WHERE ENTRUST_ID= ETR_ENTRUST.ENTRUST_ID) INNER JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
ETR_DISTRIBUTE.TRADER = #{loginUser} AND ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustCompleted},#{entrustReceive}) AND ETR_DISTRIBUTE.REC_STATUS IN(#{entrustCompleted},#{entrustReceive})
AND ETR_ENTRUST_ADD.ASSET_TYPE IN(
#{item}
)
