AND proAvailableCash>=${priceAmt}
AND proAvailableCash <= ${priceAmt2}

SELECT ETR_ENTRUST.ENTRUST_DATE createTimeVal, ETR_ENTRUST.PORTFOLIO_ID portfolioId, ETR_ENTRUST.ENTRUST_ID entrustId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.ASSET_TYPE finprodType2, case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_MARKET_ID else ETR_ENTRUST_ADD.ASSET_TYPE_10 end finprodMarketId, ETR_ENTRUST.FINPROD_ID finprodId, case when FIN_PRODUCT.FINPROD_MARKET_ID is not null then FIN_PRODUCT.FINPROD_ABBR else OPT_TARGET_INFO.TARGET_NAME end finprodAbbr, ETR_ENTRUST.PS ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, case when ETR_ENTRUST_ADD.ASSET_TYPE= 'F01' then IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0) when ETR_ENTRUST_ADD.ASSET_TYPE= 'F10' then IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0) else IFNULL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM) end entrustAmt, if ( ETR_ENTRUST_ADD.ASSET_TYPE= 'F01', IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0), if ( ETR_ENTRUST_ADD.ASSET_TYPE= 'F10', IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0), IFNULL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM) ) )- if( ETR_ENTRUST_ADD.ASSET_TYPE='F01', IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0), if ( ETR_ENTRUST_ADD.ASSET_TYPE='F10', IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0), IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT,0) ) ) proAvailableCash, case when ETR_ENTRUST_ADD.ASSET_TYPE= 'F01' then IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0) when ETR_ENTRUST_ADD.ASSET_TYPE= 'F10' then IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0) else IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT,0) end finshAmt, round(ETR_FINISH_STATUS_A.FINISH_AMT/IFNULL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM),4) percent, ETR_ENTRUST.CCY ccy, ETR_DISTRIBUTE.TRADER trader, ETR_ENTRUST.REMARK remark, (STR_TO_DATE(trunc(ETR_ENTRUST.MDATE)) - STR_TO_DATE(trunc(NOW()))) days, ETR_ENTRUST_ADD.TERM_TYPE termType FROM ETR_DISTRIBUTE INNER JOIN ETR_ENTRUST ON ETR_DISTRIBUTE.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT ETR_FINISH_STATUS.ENTRUST_ID,sum(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) ETR_FINISH_STATUS_A ON ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN OPT_TARGET_INFO ON ETR_ENTRUST_ADD.ASSET_TYPE_10 = OPT_TARGET_INFO.TARGET_ID
ETR_DISTRIBUTE.TRADER = #{loginUser} AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustAwait}
AND ETR_ENTRUST_ADD.ASSET_TYPE IN(
#{item}
)
AND ((FIN_PRODUCT.FINPROD_MARKET_ID LIKE concat_ws('', '%',#{finprodMarketId,jdbcType=VARCHAR}, '%') OR FIN_PRODUCT.FINPROD_ABBR LIKE concat_ws('', '%',#{finprodMarketId,jdbcType=VARCHAR}, '%')) OR (ETR_ENTRUST_ADD.ASSET_TYPE_10 LIKE concat_ws('', '%',#{finprodMarketId,jdbcType=VARCHAR}, '%') OR OPT_TARGET_INFO.TARGET_NAME LIKE concat_ws('', '%',#{finprodMarketId,jdbcType=VARCHAR},'%')) )
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND (case
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) then ETR_ENTRUST_ADD.BUSI_PS
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) then ETR_ENTRUST_ADD.BUSI_PS
else ETR_ENTRUST.PS end) =#{ps}
AND ETR_ENTRUST.CCY = #{ccy}
AND ETR_ENTRUST.ENTRUST_DATE >= STR_TO_DATE(#{beginDate},'%Y-%m-%d')
AND ETR_ENTRUST.ENTRUST_DATE <= STR_TO_DATE(#{endDate},'%Y-%m-%d')
AND ETR_ENTRUST_ADD.BUSI_PS = #{busiPs}
UNION all SELECT ETR_ENTRUST.ENTRUST_DATE createTimeVal, ETR_ENTRUST.PORTFOLIO_ID portfolioId, ETR_ENTRUST.ENTRUST_ID entrustId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST.FINPROD_TYPE2 finprodType2, ETR_ENTRUST.FINPROD_ID finprodMarketId, ETR_ENTRUST.FINPROD_ID finprodId, ETR_ENTRUST_ADD.ASSET_TYPE_11 finprodAbbr, ETR_ENTRUST.PS ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{IRS_TYPE} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12},#{ASSET_TYPE_16}) THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{BACK_LEND_DIRECTION} AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = #{PS} AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket, if(ETR_ENTRUST_ADD.ASSET_TYPE='F01',IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0), if(ETR_ENTRUST_ADD.ASSET_TYPE='F10',IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0),IFNULL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM))) entrustAmt, if(ETR_ENTRUST_ADD.ASSET_TYPE='F01',IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0),if(ETR_ENTRUST_ADD.ASSET_TYPE='F10',IFNULL(ETR_ENTRUST.ENTRUST_NUM * 100,0), IFNULL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM)))- if(ETR_ENTRUST_ADD.ASSET_TYPE='F01',IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),if(ETR_ENTRUST_ADD.ASSET_TYPE='F10',IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),IFNULL(ETR_FINISH_STATUS_A.FINISH_AMT,0))) proAvailableCash, if(ETR_ENTRUST_ADD.CONTRACT_RESULT='已签署完毕',ETR_ENTRUST.ENTRUST_AMT,0) finishAmt, if(ETR_ENTRUST_ADD.CONTRACT_RESULT='已签署完毕',1,0) percent, ETR_ENTRUST.CCY ccy, ETR_DISTRIBUTE.TRADER trader, ETR_ENTRUST.REMARK remark, (STR_TO_DATE(trunc(ETR_ENTRUST.MDATE)) - STR_TO_DATE(trunc(NOW()))) days, ETR_ENTRUST_ADD.TERM_TYPE termType FROM ETR_DISTRIBUTE INNER JOIN ETR_ENTRUST ON ETR_DISTRIBUTE.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT ETR_FINISH_STATUS.ENTRUST_ID,sum(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) ETR_FINISH_STATUS_A ON ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
ETR_DISTRIBUTE.TRADER = #{loginUser} AND ETR_ENTRUST.FINPROD_TYPE2 ='F36' AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustAwait}
AND ETR_ENTRUST_ADD.ASSET_TYPE IN(
#{item}
)
AND (FIN_PRODUCT.FINPROD_MARKET_ID LIKE concat_ws('', '%',#{finprodMarketId,jdbcType=VARCHAR},'%') OR FIN_PRODUCT.FINPROD_ABBR LIKE concat_ws('', '%',#{finprodMarketId,jdbcType=VARCHAR},'%'))
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND (case
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_16}) then ETR_ENTRUST_ADD.BUSI_PS
when ETR_ENTRUST_ADD.ASSET_TYPE IN (#{ASSET_TYPE_07}, #{ASSET_TYPE_08}, #{ASSET_TYPE_10}, #{ASSET_TYPE_12}) then ETR_ENTRUST_ADD.BUSI_PS
else ETR_ENTRUST.PS end) =#{ps}
AND ETR_ENTRUST.CCY = #{ccy}
AND ETR_ENTRUST.ENTRUST_DATE >= STR_TO_DATE(#{beginDate},'%Y-%m-%d')
AND ETR_ENTRUST.ENTRUST_DATE <= STR_TO_DATE(#{endDate},'%Y-%m-%d')
AND ETR_ENTRUST_ADD.BUSI_PS = #{busiPs}
